err("invalid conversion specification: '%05p'", function() return string.format("%05p", tbl) end)

-- invalid conversions and specifications
err("invalid conversion '%y' to '?'", function() return string.format("%y", 1) end)
err("invalid conversion '%' to '?'", function() return string.format("%", 1) end)
err("invalid conversion '%' to '?'", function() return string.format("%d %", 1, 2) end)
err("bad argument #2 to '?' (no value)", function() return string.format("x%") end)
err("invalid conversion '%10' to '?'", function() return string.format("%10", 1) end)
err("invalid conversion '%l' to '?'", function() return string.format("%ld", 1) end)
err("invalid conversion '%h' to '?'", function() return string.format("%hd", 1) end)
err("invalid conversion '%n' to '?'", function() return string.format("%n", 1) end)
err("invalid conversion '%5%' to '?'", function() return string.format("%5%", 1) end)
err("bad argument #2 to '?' (no value)", function() return string.format("%5%") end)
err("invalid conversion '%-%' to '?'", function() return string.format("%-%", 1) end)
err("invalid conversion '%1$' to '?'", function() return string.format("%1$d", 1) end)
err("invalid conversion '%*' to '?'", function() return string.format("%*d", 1, 2) end)
err("invalid conversion specification: '%100d'", function() return string.format("%100d", 1) end)
err("invalid conversion specification: '%.100d'", function() return string.format("%.100d", 1) end)
err("invalid conversion specification: '%0100d'", function() return string.format("%0100d", 1) end)
err("invalid conversion specification: '%-300s'", function() return string.format("%-300s", "x") end)
err("invalid conversion specification: '%.123f'", function() return string.format("%.123f", 1) end)
err("invalid conversion specification: '%123.1f'", function() return string.format("%123.1f", 1) end)
err("invalid conversion specification: '%1.2.3f'", function() return string.format("%1.2.3f", 1) end)
eq(d(string.format("%--5d|%00005d|%-+ 05d|", 1, 2, 3)), "\"1    |00002|+3   |\"")
eq(d(string.format("%" .. string.rep("-", 20) .. "d", 1)), "\"1\"")
err("invalid format (too long)", function() return string.format("%" .. string.rep("-", 21) .. "d", 1) end)
err("invalid format (too long)", function() return string.format("%" .. string.rep("0", 40) .. "d", 1) end)
eq(d(string.format("%.3f %5.1f %e", 1, 2, 3)), "\"1.000   2.0 3.000000e+00\"")
eq(d(string.format("%s %d %q %c %x", "a", 1, "b", 67, 255)), "\"a 1 \"b\" C ff\"")

assert(state.checks == 200)
